322	    @Override
323	    @Transactional
324	    public void saveOwner(Owner owner) throws DataAccessException {
325	        assertPostcodeValid(owner);
326	        assertRegistrationDateNotFuture(owner);
327	        if (owner.getTelephone() != null) {
328	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
329	        }
330	        if (owner.getEmail() != null) {
331	            owner.setEmail(normalizeEmail(owner.getEmail()));
332	        }
333	        assertEmailDomainAllowed(owner);
334	        if (owner.getAddress() != null) {
335	            owner.setAddress(normalizeAddress(owner.getAddress()));
336	        }
337	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
338	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
339	        if (owner.getCustomerCode() == null) {
340	            owner.setCustomerCode(generateCustomerCode(owner));
341	        }
342	        boolean creating = owner.isNew();
343	        if (creating) {
344	            owner.setNamesakeCount(countNamesakes(owner));
345	            assertDailyCapacity(owner);
346	            assertCityCapacity(owner);
347	        }
348	        assignHouseholdId(owner);
349	        assertIdentityUnique(owner);
350	        if (creating) {
351	            assertHouseholdUnique(owner);
352	        }
353	        ownerRepository.save(owner);
354	        populateHouseholdSize(owner);
355	        if (creating) {
356	            AUDIT.info(
357	                "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
358	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
359	                owner.getMembershipLevel(), owner.getMembershipNumber());
360	        }
361	    }
362	
363	    /**
364	     * Build a {@code customerCode} formatted {@code '<REGION>-<HASH8>'} where REGION is the region
365	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}) and
366	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
367	     * the owner's normalized telephone and {@code lastName}. The telephone is already normalized by
368	     * {@link #saveOwner(Owner)} before this runs. The {@code '<REGION>-<HASH8>'} layout is read back
369	     * by {@link Region#regionOfCustomerCode(String)}; keep the two in sync.
370	     */
371	    private String generateCustomerCode(Owner owner) {
372	        String region = Region.regionForPostcode(owner.getPostcode());
373	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
374	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
375	        String hash8 = sha256UpperHex(telephone + lastName, 8);
376	        return deduplicateCustomerCode(owner, region + "-" + hash8);
377	    }
378	
379	    /**
380	     * Returns {@code base} unchanged when no other owner already holds it; otherwise appends
381	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique among the
382	     * existing owners' {@code customerCode}s. The {@code owner} being saved is excluded from the
383	     * comparison so re-saving it does not treat its own code as a collision.
384	     */
385	    private String deduplicateCustomerCode(Owner owner, String base) {
386	        Set<String> taken = new HashSet<>();
387	        for (Owner existing : ownerRepository.findAll()) {
388	            if (!existing.getId().equals(owner.getId()) && existing.getCustomerCode() != null) {
389	                taken.add(existing.getCustomerCode());
390	            }
391	        }
392	        if (!taken.contains(base)) {
393	            return base;
394	        }
395	        int n = 2;
396	        while (taken.contains(base + "-" + n)) {
397	            n++;
398	        }
399	        return base + "-" + n;
400	    }
401	
402	    /**
403	     * The first {@code chars} upper-case hex characters of the SHA-256 digest of {@code value}'s
404	     * UTF-8 bytes.
405	     */
406	    private static String sha256UpperHex(String value, int chars) {
407	        try {
408	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
409	            byte[] hash = digest.digest(value.getBytes(StandardCharsets.UTF_8));
410	            StringBuilder sb = new StringBuilder(hash.length * 2);
411	            for (byte b : hash) {
412	                sb.append(String.format("%02X", b));
413	            }
414	            return sb.substring(0, chars);
415	        } catch (NoSuchAlgorithmException e) {
416	            throw new IllegalStateException("SHA-256 not available", e);
417	        }
418	    }
