420	    /** Maximum number of owners permitted in a single city. */
421	    private static final long CITY_OWNER_LIMIT = 50L;
422	
423	    /**
424	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
425	     * more owners, so no city can grow beyond the capacity limit.
426	     *
427	     * @throws CityOwnerLimitException if the owner's city is already at capacity
428	     */
429	    private void assertCityCapacity(Owner owner) {
430	        if (owner.getCity() == null) {
431	            return;
432	        }
433	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
434	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
435	        }
436	    }
437	
438	    /**
439	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
440	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
441	     */
442	    private static LocalDate rollToBusinessDay(LocalDate date) {
443	        switch (date.getDayOfWeek()) {
444	            case SATURDAY:
445	                return date.plusDays(2);
446	            case SUNDAY:
447	                return date.plusDays(1);
448	            default:
449	                return date;
450	        }
451	    }
452	
453	    /** Maximum number of owners permitted to be registered on a single day. */
454	    private static final long DAILY_OWNER_LIMIT = 100L;
455	
456	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
457	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
458	
459	    /**
460	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
461	     * today, reusing the same daily accumulation as the per-day create limit ({@link
462	     * #assertDailyCapacity}).
463	     */
464	    @Override
465	    @Transactional(readOnly = true)
466	    public boolean isBulkSignupWarningActive() throws DataAccessException {
467	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
468	    }
469	
470	    /**
471	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
472	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
473	     * many owners can be created on any single day.
474	     *
475	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
476	     */
477	    private void assertDailyCapacity(Owner owner) {
478	        LocalDate date = owner.getRegistrationDate();
479	        if (date == null) {
480	            return;
481	        }
482	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
483	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
484	        }
485	    }
486	
487	    private long countOwnersRegisteredOn(LocalDate date) {
488	        return ownerRepository.findAll().stream()
489	                .filter(existing -> date.equals(existing.getRegistrationDate()))
490	                .count();
491	    }
492	
493	    private long countOwnersInCity(String city) {
494	        String normalized = normalizeHouseholdValue(city);
495	        return ownerRepository.findAll().stream()
496	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
497	                .count();
498	    }
499	
500	    /**
501	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
502	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
503	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
504	     * that already existed before this create.
505	     */
506	    private int countNamesakes(Owner owner) {
507	        String firstName = normalizeHouseholdValue(owner.getFirstName());
508	        String lastName = normalizeHouseholdValue(owner.getLastName());
509	        int count = 0;
510	        for (Owner existing : ownerRepository.findAll()) {
511	            if (!existing.getId().equals(owner.getId())
512	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
513	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
514	                count++;
515	            }
516	        }
517	        return count;
518	    }
519	
520	    private static String normalizeEmail(String email) {
521	        return email == null ? null : email.toLowerCase(Locale.ROOT);
522	    }
523	
524	    /** Common street-type abbreviations expanded during address normalization. */
525	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
526	        "ST", "STREET",
527	        "RD", "ROAD",
528	        "AVE", "AVENUE");
529	
530	    /**
531	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
532	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
533	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
534	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
535	     * form.
536	     */
537	    private static String normalizeAddress(String address) {
538	        if (address == null) {
539	            return null;
540	        }
541	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
542	        if (collapsed.isEmpty()) {
543	            return "";
544	        }
545	        String[] tokens = collapsed.split(" ");
546	        StringBuilder sb = new StringBuilder(collapsed.length());
547	        for (int i = 0; i < tokens.length; i++) {
548	            if (i > 0) {
549	                sb.append(' ');
550	            }
551	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
552	        }
553	        return sb.toString();
554	    }
555	
556	    private static String normalizeTelephone(String telephone) {
557	        return telephone == null ? null : E164Telephone.toE164(telephone);
558	    }
559	
560	    /**
561	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
562	     * that of another owner. This single check consolidates the former separate telephone, email and
563	     * household duplicate rules: because the normalized telephone is part of the key, two members of
564	     * the same household (same {@code householdId}) with different telephones have different keys and
565	     * are both allowed — only an exact full-key match is a duplicate.
566	     *
567	     * @throws DuplicateIdentityException if another owner already has the same identity key
568	     */
569	    private void assertIdentityUnique(Owner owner) {
570	        String identityKey = owner.getIdentityKey();
571	        for (Owner existing : ownerRepository.findAll()) {
572	            if (!existing.getId().equals(owner.getId()) && identityKey.equals(existing.getIdentityKey())) {
573	                throw new DuplicateIdentityException(identityKey);
574	            }
575	        }
576	    }
577	
578	    /**
579	     * Assigns {@code owner} its deterministic {@code householdId}: the first 12 upper-case hex
580	     * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}, so all
581	     * owners that share a normalized {@code lastName} and {@code postcode} automatically share the
582	     * same household. Left {@code null} when either the lastName or the postcode is absent, since a
583	     * household is keyed on both.
584	     */
585	    private void assignHouseholdId(Owner owner) {
586	        String lastName = normalizeHouseholdValue(owner.getLastName());
587	        String postcode = owner.getPostcode();
588	        if (lastName.isEmpty() || postcode == null || postcode.isBlank()) {
589	            owner.setHouseholdId(null);
590	            return;
591	        }
592	        owner.setHouseholdId(generateHouseholdId(lastName, postcode));
593	    }
594	
595	    /**
596	     * Rejects creating {@code owner} when another owner already belongs to the same household — i.e.
597	     * shares its computed {@code householdId} (same normalized {@code lastName} and {@code postcode}).
598	     * Because the household is keyed on those two fields, a second such owner is a household
599	     * duplicate unless it declares {@code sharesHousehold}, in which case it is admitted as a
600	     * declared household member (and, being declared, is never a suspected duplicate). No-op when the
601	     * owner has no household id.
602	     *
603	     * @throws HouseholdDuplicateException if another owner already shares the household and the owner
604	     *     did not declare {@code sharesHousehold}
605	     */
606	    private void assertHouseholdUnique(Owner owner) {
607	        String householdId = owner.getHouseholdId();
608	        if (householdId == null || householdId.isBlank() || owner.isSharesHousehold()) {
609	            return;
610	        }
611	        for (Owner existing : ownerRepository.findAll()) {
612	            if (!existing.getId().equals(owner.getId()) && householdId.equals(existing.getHouseholdId())) {
613	                throw new HouseholdDuplicateException(householdId);
614	            }
615	        }
616	    }
617	
618	    /**
619	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
620	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
621	     * reaching into the data store. A {@code null} owner or one without a household id is left at
622	     * size 0.
623	     */
624	    private void populateHouseholdSize(Owner owner) {
625	        if (owner == null) {
626	            return;
627	        }
628	        String householdId = owner.getHouseholdId();
629	        if (householdId == null || householdId.isBlank()) {
630	            owner.setHouseholdSize(0);
631	            return;
632	        }
633	        int count = 0;
634	        for (Owner existing : ownerRepository.findAll()) {
635	            if (householdId.equals(existing.getHouseholdId())) {
636	                count++;
637	            }
638	        }
639	        owner.setHouseholdSize(count);
640	    }
641	
642	    /**
643	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
644	     * store, so a list/page of owners is counted without a per-owner query.
645	     *
646	     * @see #populateHouseholdSize(Owner)
647	     */
648	    private void populateHouseholdSizes(Collection<Owner> owners) {
649	        if (owners.isEmpty()) {
650	            return;
651	        }
652	        Map<String, Integer> sizes = new HashMap<>();
653	        for (Owner existing : ownerRepository.findAll()) {
654	            String householdId = existing.getHouseholdId();
655	            if (householdId != null && !householdId.isBlank()) {
656	                sizes.merge(householdId, 1, Integer::sum);
657	            }
658	        }
659	        for (Owner owner : owners) {
660	            String householdId = owner.getHouseholdId();
661	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
662	        }
663	    }
664	
665	    /**
666	     * Derives the deterministic {@code householdId} from the normalized {@code lastName} and
667	     * {@code postcode}: the first 12 upper-case hex characters of SHA-256 over
668	     * {@code lastName + '|' + postcode}, so all owners in the same household share the same
669	     * identifier.
670	     */
671	    private static String generateHouseholdId(String lastName, String postcode) {
672	        return sha256UpperHex(lastName + "|" + postcode, 12);
673	    }
674	
675	    /**
676	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
677	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
678	     */
679	    private static String normalizeHouseholdValue(String value) {
680	        if (value == null) {
681	            return "";
682	        }
683	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
684	    }
685	
686	    @Override
687	    @Transactional(readOnly = true)
688	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
689	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
690	        populateHouseholdSizes(owners);
691	        return owners;
692	    }
693	
694	    @Override
695	    @Transactional(readOnly = true)
696	    public Collection<Visit> findVisitsByPetId(int petId) {
697	        return visitRepository.findByPetId(petId);
698	    }
699	
700	    @Override
701	    @Transactional(readOnly = true)
702	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
703	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
704	    }
705	
706	    private <T> T findEntityById(Supplier<T> supplier) {
707	        try {
708	            return supplier.get();
709	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
710	            // Just ignore not found exceptions for Jdbc/Jpa realization
711	            return null;
712	        }
713	    }
714	
715	}
